CREATE TABLE reviews(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),booking_id TEXT REFERENCES bookings(id),display_name TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),feedback TEXT NOT NULL,consent INTEGER NOT NULL CHECK(consent=1),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),moderation_reason TEXT,version INTEGER NOT NULL DEFAULT 1,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL,moderated_at INTEGER,UNIQUE(business_id,idempotency_key));
CREATE INDEX reviews_public ON reviews(business_id,status,created_at);
CREATE TABLE review_moderation(id TEXT PRIMARY KEY,review_id TEXT NOT NULL REFERENCES reviews(id),actor_id TEXT NOT NULL REFERENCES owners(id),from_status TEXT NOT NULL,to_status TEXT NOT NULL,reason TEXT,created_at INTEGER NOT NULL);
